-- 46 Sea Cove: swims the listener and keeps the cove alive. How it sounds is
-- the engine's: the cave and the water are `audio_zone`s, so the drips ring
-- once you are in the cave and the whole world goes dull under the surface.
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/46-sea-cove.scene"
local WATER_Y = -40.0
local SPEED = 230
local KELP = { { x = -120.0 }, { x = -30.0 }, { x = 60.0 }, { x = 250.0 }, { x = 330.0 }, { x = 520.0 } }
local FISH = { { x = -200.0, y = -150.0 }, { x = 0.0, y = -230.0 }, { x = 150.0, y = -120.0 }, { x = 380.0, y = -200.0 }, { x = -60.0, y = -290.0 } }
local captions = true
local swimmer, bubbles, status, cave_zone, water_zone, music
local foams, gulls = {}, {}
local px, py = -300, WATER_Y + 6
local was_under = false
local zones_on, music_on = true, true
local t, facing = 0, 1

function init(entity)
    swimmer = Entity.find_by_name("Swimmer")
    bubbles = Entity.find_by_name("Bubbles")
    status = Entity.find_by_name("Status")
    cave_zone = Entity.find_by_name("CaveZone")
    water_zone = Entity.find_by_name("WaterZone")
    music = Entity.find_by_name("Music")
    for i = 1, 2 do
        foams[i] = Entity.find_by_name("Foam" .. i)
        gulls[i] = Entity.find_by_name("Gull" .. i)
    end
    for i, k in ipairs(KELP) do k.e = Entity.find_by_name("Kelp" .. i) end
    for i, f in ipairs(FISH) do f.e = Entity.find_by_name("Fish" .. i); f.phase = i * 1.7 end
end

local function held(a, b) return Input.is_key_pressed(a) or Input.is_key_pressed(b) end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    t = t + dt

    local dx, dy = 0, 0
    if held("A", "Left") then dx = dx - 1 end
    if held("D", "Right") then dx = dx + 1 end
    if held("W", "Up") then dy = dy + 1 end
    if held("S", "Down") then dy = dy - 1 end
    px = math.max(-600, math.min(600, px + dx * SPEED * dt))
    -- Swimmers float: above the surface only a little.
    py = math.max(-300, math.min(WATER_Y + 10, py + dy * SPEED * dt))
    if dx ~= 0 then facing = dx end
    local bob = (py >= WATER_Y - 2) and math.sin(t * 2.2) * 3 or 0
    if swimmer then
        Transform.set_position(swimmer, px, py + bob)
        Transform.set_scale(swimmer, facing, 1)
    end

    local under = py < WATER_Y - 12
    if under ~= was_under then
        Audio.play_sound_at("sounds/cove_splash.wav", px, WATER_Y, 0.8)
        was_under = under
    end
    if bubbles then
        Transform.set_position(bubbles, px + facing * 30, py + 6)
        Particles.set_active(bubbles, under)
    end

    if Input.is_key_just_pressed("E") then
        zones_on = not zones_on
        Transform.set_position(cave_zone, zones_on and 390 or 5000, 40)
        Transform.set_position(water_zone, zones_on and 0 or 5000, WATER_Y - 200)
    end
    if Input.is_key_just_pressed("M") and music then
        music_on = not music_on
        Audio.set_bus_volume("music", music_on and 1 or 0)
    end

    -- The cove moves: foam drifts, kelp sways, fish wander, gulls glide.
    for i, f in ipairs(foams) do
        if f then Transform.set_position(f, ((t * (i == 1 and 30 or -45)) % 256) - 128, WATER_Y + (i - 1) * 3) end
    end
    for i, k in ipairs(KELP) do
        if k.e then Transform.set_rotation(k.e, 0.08 * math.sin(t * 0.9 + i * 1.3)) end
    end
    for _, f in ipairs(FISH) do
        if f.e then
            local s = math.sin(t * 0.35 + f.phase)
            Transform.set_position(f.e, f.x + 90 * s, f.y + 10 * math.sin(t * 1.3 + f.phase))
            Transform.set_scale(f.e, (math.cos(t * 0.35 + f.phase) >= 0) and 1 or -1, 1)
        end
    end
    for i, g in ipairs(gulls) do
        if g then
            local gx = ((t * (25 + 10 * i) + i * 500) % 1600) - 800
            Transform.set_position(g, gx, 230 + 40 * i + 12 * math.sin(t * 0.8 + i))
        end
    end

    if status then
        local where = "open air"
        if under then where = "under water - everything muffled"
        elseif px > 200 and py > -60 then where = "in the cave - the drips ring" end
        if not zones_on then where = where .. "  (zones off)" end
        UI.set_text(status, where)
    end
end
